function validate(input) {
  const [arr, callback, context] = input;
  if (!Array.isArray(arr)) return 'arr must be a JSON array.';
  if (arr.length > 100000) return 'arr has at most 10^5 elements.';
  const names = ['double', 'negate', 'context', 'index', 'addIndex', 'runningSum'];
  if (!names.includes(callback)) return `callback must be one of ${names.join(', ')}.`;
  if (!context || typeof context !== 'object' || Array.isArray(context)) return 'context must be a JSON object such as { "context": true }.';
  if (['double', 'addIndex', 'runningSum'].includes(callback)) {
    for (const value of arr) {
      if (!Number.isInteger(value) || Math.abs(value) > 1000000) return `With "${callback}", every element must be an integer from -10^6 to 10^6.`;
    }
  }
  return null;
}

