function adapt(input, solve, kit) {
  const [arr, name, context] = input;
  // Each named callback writes through its third argument, so it only works on the real array.
  const callbacks = {
    double: function (val, i, array) { array[i] = val * 2; },
    negate: function (val, i, array) { array[i] = !val; },
    context: function (val, i, array) { array[i] = this && this !== globalThis ? this : null; },
    index: function (val, i, array) { array[i] = i; },
    addIndex: function (val, i, array) { array[i] = val + i; },
    runningSum: function (val, i, array) { array[i] = (i > 0 ? array[i - 1] : 0) + val; },
  };
  if (typeof arr.forEach !== 'function') throw new Error('Arrays have no forEach method: assign a function to Array.prototype.forEach.');
  if (/\[native code\]/.test(Function.prototype.toString.call(arr.forEach))) throw new Error('arr.forEach is still the built-in method: assign your own function to Array.prototype.forEach.');
  kit.trace(`arr.forEach(${name}, ${JSON.stringify(context)}) is called`);
  const result = arr.forEach(callbacks[name], context);
  if (result !== undefined) throw new Error('forEach must not return anything.');
  return arr;
}

