function generate(rand, size) {
  const names = ['double', 'negate', 'context', 'index', 'addIndex', 'runningSum'];
  const callback = names[Math.floor(rand() * names.length)];
  const numeric = ['double', 'addIndex', 'runningSum'].includes(callback);
  const value = () => {
    if (numeric) return Math.floor(rand() * 201) - 100;
    const roll = rand();
    if (roll < 0.4) return Math.floor(rand() * 21) - 10;
    if (roll < 0.6) return rand() < 0.5;
    if (roll < 0.75) return ['', 'a', 'word'][Math.floor(rand() * 3)];
    if (roll < 0.85) return null;
    return { key: Math.floor(rand() * 5) };
  };
  const length = size === 'small' ? Math.floor(rand() * 6) : 1500 + Math.floor(rand() * 501);
  const arr = Array.from({ length }, value);
  const context = { context: Math.floor(rand() * 10), tag: ['a', 'b', 'c'][Math.floor(rand() * 3)] };
  return [arr, callback, context];
}
